mapper.select:
SELECT m.mission_id, m.child_id, m.title, m.description, m.reward_amount, m.status, m.created_at FROM mission m WHERE m.child_id = #{childId}
AND m.status != 'CANCELED'
AND m.status IN ('ASSIGNED', 'REJECTED')
AND m.status = 'SUBMITTED'
AND m.status = 'APPROVED'
AND m.status = 'CANCELED'
AND m.mission_id < #{cursorId}
ORDER BY m.mission_id DESC LIMIT #{limit}
